create table public.sb_vitola_catalog (
  slug text primary key check (slug = 'la-vitola'),
  revision bigint not null default 1 check (revision > 0),
  draft jsonb not null,
  published jsonb not null
);
create table public.sb_vitola_admins (
  user_id uuid primary key references auth.users(id) on delete cascade
);
alter table public.sb_vitola_admins enable row level security;
alter table public.sb_vitola_catalog enable row level security;
revoke all on public.sb_vitola_catalog, public.sb_vitola_admins from public, anon, authenticated;
grant select on public.sb_vitola_admins to authenticated;
create policy vitola_own_membership on public.sb_vitola_admins for select to authenticated using (user_id = (select auth.uid()));
grant select, update (draft,published,revision) on public.sb_vitola_catalog to authenticated;
create policy vitola_read on public.sb_vitola_catalog for select to authenticated using (exists (select 1 from public.sb_vitola_admins where user_id = (select auth.uid())));
create policy vitola_write on public.sb_vitola_catalog for update to authenticated using (exists (select 1 from public.sb_vitola_admins where user_id = (select auth.uid()))) with check (exists (select 1 from public.sb_vitola_admins where user_id = (select auth.uid())));
create function public.sb_vitola_published() returns jsonb language sql stable security definer set search_path = '' as $$ select published from public.sb_vitola_catalog where slug='la-vitola' $$;
revoke all on function public.sb_vitola_published() from public;
grant execute on function public.sb_vitola_published() to anon, authenticated;
insert into public.sb_vitola_catalog(slug,draft,published) select 'la-vitola',menu,menu from (select $catalog${"restaurante":{"nombre":"La Vitola","descripcion":"Tacos con papa y hamburguesas de pan artesanal.","whatsapp":"529611792804","horario":"Lunes a sábado, de 6:00 p. m. a 11:30 p. m.","direccion":"Calle Central, entre Avenida Central y Primera Norte, Col. Terán.","moneda":"MXN"},"modalidades":["domicilio","sin-domicilio"],"costoEnvio":null,"categorias":[{"id":"tacos","nombre":"Tacos con papa","etiquetaCorta":"Tacos"},{"id":"hamburguesas","nombre":"Hamburguesas","descripcion":"Pan artesanal y carne de res de 120 g."},{"id":"extras","nombre":"Extras"},{"id":"bebidas","nombre":"Bebidas"}],"productos":[{"id":"taco-campechano","categoria":"tacos","nombre":"Taco campechano","precio":25},{"id":"taco-chorizo","categoria":"tacos","nombre":"Taco de chorizo","precio":25},{"id":"taco-pastor","categoria":"tacos","nombre":"Taco al pastor","precio":25},{"id":"taco-bistec","categoria":"tacos","nombre":"Taco de bistec de res","precio":30},{"id":"buakaw","categoria":"hamburguesas","nombre":"La Buakaw","precio":95,"descripcion":"Carne de res, queso amarillo, jamón, lechuga, tomate, cebolla caramelizada y tocineta."},{"id":"saenchai","categoria":"hamburguesas","nombre":"La Saenchai","precio":115,"descripcion":"Carne de res, queso amarillo, jamón, lechuga, tomate, cebolla caramelizada, tocineta y salsa BBQ."},{"id":"rodtang","categoria":"hamburguesas","nombre":"La Rodtang","precio":115,"descripcion":"Carne de res, queso amarillo, jamón, lechuga, tomate, cebolla caramelizada, piña caramelizada y tocineta."},{"id":"ramon-dekkers","categoria":"hamburguesas","nombre":"La Ramón Dekkers","precio":125,"descripcion":"Carne de res, queso amarillo, jamón, lechuga, tomate, cebolla caramelizada, tocineta, chorizo argentino y aderezo ranch."},{"id":"giorgio-petrosyan","categoria":"hamburguesas","nombre":"La Giorgio Petrosyan","precio":135,"descripcion":"Carne de res, queso amarillo, jamón, lechuga, tomate, cebolla caramelizada, tocineta, queso gouda y pepperoni."},{"id":"carne-extra","categoria":"extras","nombre":"Carne extra (120 g)","precio":45},{"id":"tocineta","categoria":"extras","nombre":"Tocineta","precio":20},{"id":"pina","categoria":"extras","nombre":"Piña","precio":20},{"id":"pepperoni","categoria":"extras","nombre":"Pepperoni","precio":20},{"id":"gouda","categoria":"extras","nombre":"Queso gouda","precio":20},{"id":"chorizo-argentino","categoria":"extras","nombre":"Chorizo argentino","precio":20},{"id":"ranch","categoria":"extras","nombre":"Salsa ranch","precio":20},{"id":"bbq","categoria":"extras","nombre":"Salsa BBQ","precio":20},{"id":"aguas-naturales","categoria":"bebidas","nombre":"Aguas naturales (500 ml)","precio":25},{"id":"vida-mineralizada","categoria":"bebidas","nombre":"Refresco Vida mineralizada","precio":25},{"id":"agua-pura","categoria":"bebidas","nombre":"Agua pura (1 L)","precio":25},{"id":"coca-cola","categoria":"bebidas","nombre":"Coca-Cola (355 ml)","precio":30}]}$catalog$::jsonb menu) seeded;
